import{api,totalBars,cueBar}from './api.js';
let db,page='library',activeSet=null,draft=null,selected=new Set(),unlocked=false,dirty=false,setEtag=null;const filters={q:'',genre:'',tag:'',key:'',min:'',max:''};
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),time=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`,artist=t=>t.artists.map(a=>db.artists.find(x=>x.id===a.id)?.name||'Unknown').join(', '),options=(xs,value='')=>xs.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}
function stats(items){const ts=items.map(i=>db.tracks.find(t=>t.id===i.track_id));return `<div class="stats"><div class="stat"><span class="eyebrow">Tracks in set</span><strong>${ts.length.toString().padStart(2,'0')}</strong><small>In your chosen order</small></div><div class="stat"><span class="eyebrow">Average BPM</span><strong>${ts.length?(ts.reduce((a,t)=>a+t.bpm,0)/ts.length).toFixed(2):'—'}</strong><small>Across selected tracks</small></div><div class="stat"><span class="eyebrow">Source-track duration</span><strong>${time(ts.reduce((a,t)=>a+t.duration,0))}</strong><small>Full tracks, not mixed performance time</small></div></div>`}
function filtered(){if(filters.min!==''&&filters.max!==''&&Number(filters.min)>Number(filters.max))return [];return db.tracks.filter(t=>(!filters.q||`${t.title} ${artist(t)}`.toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.genre||t.genres.includes(filters.genre))&&(!filters.tag||t.tags.includes(filters.tag))&&(!filters.key||t.key===filters.key)&&(filters.min===''||t.bpm>=Number(filters.min))&&(filters.max===''||t.bpm<=Number(filters.max)))}
function filterUI(){return `<div class="filters"><input type="search" id="search" placeholder="Search tracks or artists…" aria-label="Search tracks or artists" value="${esc(filters.q)}"><select data-filter="genre" aria-label="Genre"><option value="">All genres</option>${options(db.genres,filters.genre)}</select><select data-filter="tag" aria-label="Tag"><option value="">All tags</option>${options(db.tags,filters.tag)}</select><select data-filter="key" aria-label="Musical key"><option value="">All keys</option>${options([...new Set(db.tracks.map(t=>t.key).filter(Boolean))],filters.key)}</select><input aria-label="Minimum BPM inclusive" id="min" type="number" step="any" placeholder="Min BPM" value="${esc(filters.min)}"><input aria-label="Maximum BPM inclusive" id="max" type="number" step="any" placeholder="Max BPM" value="${esc(filters.max)}"><button class="ghost small" data-action="clear">Clear</button></div>`}
function trackIdentity(t){return `<div class="trackcell"><span class="art">${esc(t.title[0])}</span><div><button class="textbutton tracktitle" data-track="${t.id}">${esc(t.title)}</button><span class="sub">${esc(artist(t))}</span></div></div>`}
function render(){const isBuilder=page==='sets'&&activeSet!==null;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="logo">CUE<span>↗</span></div><div class="eyebrow">The set workspace</div><nav>${[['library','▤','Track Library'],['sets','≋','DJ Sets']].map(([p,i,n])=>`<button data-nav="${p}" class="${page===p?'active':''}"><span class="navicon">${i}</span>${n}</button>`).join('')}</nav><div class="sidefoot"><span class="dot"></span>EC2 database<br>${unlocked?'Editing enabled':'Read-only browsing'}<br><button class="ghost small" data-action="token">${unlocked?'Lock editing':'Enable editing'}</button><button class="ghost small" data-action="refresh">Refresh data</button></div></aside><main class="main"><header class="topbar"><span>Workspace <span style="margin:0 10px;color:#56615c">/</span> ${isBuilder?'Set builder':page==='library'?'Track library':'DJ sets'}</span><span class="badge">METADATA DEMO · NO AUDIO</span></header><div class="content">${page==='library'?library():(isBuilder?builder():sets())}</div></main></div>`;bind()}
function library(){return `<div class="heading"><div><div class="eyebrow" style="margin-bottom:12px">Your collection, organised</div><h1>Track Library<span style="color:#64716c">.</span></h1><p>Find the right track. Shape your next set.</p></div><div class="actions"><button data-action="newset">Create set${selected.size?` (${selected.size})`:''}</button><button class="primary" data-action="addtrack">＋ Add track</button></div></div><div class="sectionbar"><h2>All tracks <span class="count"> / ${db.tracks.length}</span></h2><span class="count">${selected.size?selected.size+' selected':'A shared catalogue'}</span></div>${filterUI()}<div id="results">${table()}</div><div class="footerline"><span>Fictional music records · saved to PostgreSQL</span><span>Constant BPM · 4/4 timing</span></div>`}
function table(){return `<div class="tablewrap"><table><thead><tr><th></th><th>Track / Artist</th><th>BPM</th><th>Key</th><th>Duration</th><th>Genre</th><th>Tags</th><th></th></tr></thead><tbody>${filtered().map(t=>`<tr><td><input type="checkbox" data-select="${t.id}" aria-label="Select ${esc(t.title)}" ${selected.has(t.id)?'checked':''}></td><td>${trackIdentity(t)}</td><td>${t.bpm}</td><td><span class="chip key">${esc(t.key||'—')}</span></td><td>${time(t.duration)}</td><td>${t.genres.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</td><td>${t.tags.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</td><td><button class="small ghost" data-track="${t.id}">Details ↗</button></td></tr>`).join('')}</tbody></table>${filtered().length?'':`<div class="empty">${filters.min!==''&&filters.max!==''&&Number(filters.min)>Number(filters.max)?'Minimum BPM must not exceed maximum BPM.':'No tracks match these filters. Try clearing a filter.'}</div>`}</div>`}
function sets(){return `<div class="heading"><div><div class="eyebrow" style="margin-bottom:12px">From collection to performance</div><h1>DJ Sets.</h1><p>A little structure. Room for spontaneity.</p></div><button class="primary" data-action="newset">＋ Create set</button></div><div class="sectionbar"><h2>Your sets <span class="count"> / ${db.sets.length}</span></h2><span class="count">Open a set to arrange its tracks</span></div><div class="setgrid">${db.sets.map((s,i)=>`<button class="setcard" data-set="${s.id}"><div class="setart">${String(i+1).padStart(2,'0')} / ≋</div><h2>${esc(s.name)}</h2><p>${s.items.length} tracks · ${time(s.items.reduce((a,i)=>a+db.tracks.find(t=>t.id===i.track_id).duration,0))} source time</p><div class="sectionbar" style="margin-bottom:0"><span class="badge">${s.items.length?'READY TO ARRANGE':'EMPTY SET'}</span><span>↗</span></div></button>`).join('')}</div>`}
function builder(){return `<div class="heading"><div><button class="textbutton count" data-action="back">← All sets</button><h1 style="margin-top:14px">${esc(draft.name)}</h1><p>Find your flow, one track at a time.</p></div><div class="actions"><button class="danger" data-action="deleteset">Delete set</button><button data-action="rename">Rename</button><button class="primary" data-action="saveset">Save changes</button></div></div>${stats(draft.items)}<div class="builder"><section class="pane"><div class="sectionbar" style="margin-top:0"><h2>Find tracks</h2><span class="count">${db.tracks.length} in library</span></div>${filterUI()}<div id="builderresults">${builderTracks()}</div></section><section class="pane"><div class="sectionbar" style="margin-top:0"><h2>Set order</h2><span class="count">Drag or use arrows</span></div>${draft.items.map((i,n)=>{const t=db.tracks.find(t=>t.id===i.track_id);return `<div class="songrow" draggable="true" data-drag="${n}"><span class="number">${String(n+1).padStart(2,'0')}</span><div class="info"><button class="textbutton" data-track="${t.id}"><strong>${esc(t.title)}</strong></button><span class="sub">${esc(artist(t))} · ${t.bpm} BPM · ${esc(t.key)}</span><textarea class="note" data-note="${t.id}" aria-label="Performance notes for ${esc(t.title)}" placeholder="Performance notes for this set…">${esc(i.notes)}</textarea></div><div style="display:grid;gap:5px"><button class="small ghost" data-move="${n},-1" aria-label="Move ${esc(t.title)} up" ${n===0?'disabled':''}>↑</button><button class="small ghost" data-move="${n},1" aria-label="Move ${esc(t.title)} down" ${n===draft.items.length-1?'disabled':''}>↓</button><button class="small ghost" data-remove="${t.id}" aria-label="Remove ${esc(t.title)}">×</button></div></div>`}).join('')||'<div class="empty">Your set starts here.<br>Add tracks from the library on the left.</div>'}<p class="hint">Notes belong to this set. Save changes when your arrangement is ready.</p></section></div>`}
function builderTracks(){return filtered().map(t=>`<div class="songrow"><div class="info"><button class="textbutton" data-track="${t.id}"><strong>${esc(t.title)}</strong></button><span class="sub">${esc(artist(t))} · ${t.bpm} BPM · ${esc(t.key)}</span></div><button class="small ${draft.items.some(i=>i.track_id===t.id)?'ghost':'primary'}" data-add="${t.id}" ${draft.items.some(i=>i.track_id===t.id)?'disabled':''}>${draft.items.some(i=>i.track_id===t.id)?'Added':'＋ Add'}</button></div>`).join('')||'<div class="empty">No matching tracks</div>'}
function modal(title,body){$('#modal').innerHTML=`<div class="modalhead"><h2>${esc(title)}</h2><button class="ghost small" id="closemodal" aria-label="Close dialog">×</button></div>${body}`;$('#closemodal').onclick=()=>$('#modal').close();if(!$('#modal').open)$('#modal').showModal()}
function simpleForm(title,fields,submit,buttonLabel='Save'){modal(title,`<form id="simpleform">${fields}<div class="error" id="error" role="alert"></div><div class="modalfoot"><button class="${buttonLabel.startsWith('Delete')?'danger':'primary'}">${esc(buttonLabel)}</button></div></form>`);const form=$('#simpleform');form.querySelectorAll('input:not([type=number]),textarea').forEach(el=>el.maxLength=2000);form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;$('#closemodal').disabled=true;const preventClose=e=>e.preventDefault();$('#modal').addEventListener('cancel',preventClose);try{await submit(new FormData(form));$('#modal').close();render()}catch(error){showError(error,$('#error'));if(error.status===412||!error.status||error.status>=500)button.dataset.stale='true'}finally{$('#modal').removeEventListener('cancel',preventClose);$('#closemodal').disabled=false;button.disabled=button.dataset.stale==='true'}}}
function newSet(){requireWrite();simpleForm('Create a DJ set',`<label>Set name<input name="name" maxlength="2000" required></label><p class="hint">${selected.size} selected tracks will be added in one transaction. An empty set is valid.</p>`,async f=>{const result=await api.create('sets',{name:f.get('name').trim(),items:[...selected].map(track_id=>({track_id,notes:''}))});upsert('sets',result.data);selected.clear();page='sets';activeSet=result.data.id;draft=structuredClone(result.data);setEtag=result.etag;dirty=false;toast('Set created')})}
function detail(id,tab='metadata'){const t=db.tracks.find(t=>t.id===id);modal(t.title,`<p>${esc(artist(t))} <span class="chip key">${esc(t.key)}</span></p><div class="tabs">${['metadata','timing','cues'].map(x=>`<button class="${tab===x?'active':''}" data-detailtab="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div>${tab==='cues'?cueUI(t):tab==='timing'?`<div class="stats"><div class="stat">BPM<strong>${t.bpm}</strong></div><div class="stat">Duration<strong>${time(t.duration)}</strong></div><div class="stat">Total bars<strong>${totalBars(t)??'Unknown'}</strong></div></div><p>First downbeat: ${t.downbeat===null?'Unknown':t.downbeat+' seconds'}</p><p class="hint">Bars use constant BPM and 4/4 time. Calculated values are read-only.</p><div class="modalfoot"><button class="primary" id="edittrack">Edit timing</button></div>`:`<div class="formgrid"><div><h3>Artist credits</h3>${t.artists.map(a=>`<p>${esc(db.artists.find(x=>x.id===a.id)?.name||'Unknown')} <span class="sub">${esc(a.role)}</span></p>`).join('')}</div><div><h3>Album</h3><p>${esc(db.albums.find(a=>a.id===t.album)?.name||'No album')}</p></div><div><h3>Genres & tags</h3>${[...t.genres,...t.tags].map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div><div><h3>Language / Instrumental</h3><p>${esc(t.language||'Unknown')} / ${t.instrumental===null?'Unknown':t.instrumental?'Yes':'No'}</p></div></div><div class="modalfoot"><button class="primary" id="edittrack">Edit metadata</button></div>`}`);$('#modal').insertAdjacentHTML('beforeend','<div class="modalfoot"><button class="danger" id="deletetrack">Delete track</button></div>');$('#deletetrack').onclick=()=>run(()=>deleteTrack(id));document.querySelectorAll('[data-detailtab]').forEach(b=>b.onclick=()=>detail(id,b.dataset.detailtab));if($('#edittrack'))$('#edittrack').onclick=()=>run(()=>trackForm(t));if($('#addcue'))$('#addcue').onclick=()=>run(()=>cueForm(t));document.querySelectorAll('[data-editcue]').forEach(b=>b.onclick=()=>run(()=>cueForm(t,db.cues.find(c=>c.id===+b.dataset.editcue))));document.querySelectorAll('[data-deletecue]').forEach(b=>b.onclick=()=>run(()=>deleteCue(+b.dataset.deletecue,id)));gate()}
function cueUI(t){const cues=db.cues.filter(c=>c.track_id===t.id).sort((a,b)=>a.seconds-b.seconds);return `<div class="sectionbar"><h3>Cue annotations</h3><button class="primary small" id="addcue">＋ Add cue</button></div><div class="ruler">${cues.map(c=>`<span class="marker" style="left:${Math.min(90,c.seconds/t.duration*100)}%;border-color:${esc(safeColor(c.color))}">${esc(c.name)}</span>`).join('')}</div><div class="footerline"><span>0:00</span><span>${time(t.duration)}</span></div>${cues.map(c=>`<div class="songrow"><div class="info"><strong><span class="cuedot" style="background:${esc(safeColor(c.color))}"></span>${esc(c.name)}</strong><span class="sub">${c.seconds}s · ${esc(c.type)} · ${cueBar(t,c)===null?(t.downbeat===null?'Bar unknown':'Before first downbeat'):'Bar '+cueBar(t,c)}</span><p class="hint">${esc(c.comment)}</p></div><button class="small" data-editcue="${c.id}">Edit</button><button class="small ghost" data-deletecue="${c.id}" aria-label="Delete ${esc(c.name)}">×</button></div>`).join('')||'<div class="empty">No cues yet. Add your first annotation.</div>'}<p class="hint">A metadata time ruler. No audio playback or waveform analysis.</p>`}
async function cueForm(t,c={name:'',type:'Entry',seconds:0,color:'#c6ef93',comment:''}){requireWrite();let etag;if(c.id){const fresh=await api.get('cues',c.id);c=fresh.data;etag=fresh.etag}simpleForm(c.id?'Edit cue':'Add cue',`<div class="formgrid"><label>Name<input name="name" value="${esc(c.name)}" required></label><label>Type<input name="type" value="${esc(c.type)}" required list="cuetypes"><datalist id="cuetypes"><option>Entry</option><option>Exit</option><option>Phrase</option><option>Breakdown</option></datalist></label><label>Position in seconds<input name="seconds" type="number" step="any" min="0" value="${c.seconds}" required></label><label>Colour<input name="color" placeholder="#c6ef93 or blank" value="${esc(c.color)}"></label><label class="wide">Comment<input name="comment" value="${esc(c.comment)}"></label></div><p class="hint">Must be less than ${t.duration} seconds. Bar position is calculated automatically.</p>`,async f=>{const body={name:f.get('name').trim(),type:f.get('type').trim(),seconds:Number(f.get('seconds')),color:f.get('color')||null,comment:f.get('comment')||null};if(body.seconds>=t.duration)throw validation('Cue timestamp must be less than the track duration.');const result=c.id?await api.update('cues',c.id,body,etag):await api.createTrackCue(t.id,body);upsert('cues',result.data);toast('Cue saved')})}

async function trackForm(t){requireWrite();let etag;if(t){const fresh=await api.get('tracks',t.id);t=fresh.data;etag=fresh.etag}const isNew=!t;t=t||{title:'',bpm:120,key:'Am',duration:300,downbeat:null,album:null,artists:[],genres:[],tags:[],language:null,instrumental:null};simpleForm(isNew?'Add a track':'Edit track',`<div class="formgrid"><label class="wide">Track title<input name="title" value="${esc(t.title)}" required></label><label>BPM<input name="bpm" type="number" step="any" min="0.0001" value="${t.bpm}" required></label><label>Musical key<input name="key" value="${esc(t.key)}"></label><label>Duration in seconds<input name="duration" type="number" step="any" min="0.0001" value="${t.duration}" required></label><label>First downbeat in seconds<input name="downbeat" type="number" step="any" min="0" value="${t.downbeat??''}" placeholder="Unknown"></label><label>Album<select name="album"><option value="">No album</option>${db.albums.map(a=>`<option value="${a.id}" ${a.id===t.album?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Instrumental<select name="instrumental"><option value="">Unknown</option><option value="yes" ${t.instrumental===true?'selected':''}>Yes</option><option value="no" ${t.instrumental===false?'selected':''}>No</option></select></label><label>Language<input name="language" value="${esc(t.language)}" placeholder="Unknown"></label><div></div><div class="wide"><h3>Artist credits</h3><p class="hint">Select contributors and enter one role for each. At least one is required.</p>${db.artists.map(a=>{const credit=t.artists.find(x=>x.id===a.id);return `<div class="songrow"><input type="checkbox" name="artist" value="${a.id}" aria-label="Credit ${esc(a.name)}" ${credit?'checked':''}><span style="flex:1">${esc(a.name)}</span><input name="role-${a.id}" aria-label="Role for ${esc(a.name)}" value="${esc(credit?.role||'Main artist')}"></div>`}).join('')}</div><label>Genres<select name="genres" multiple>${recordOptions(db.genre_records)} </select></label><label>Tags<select name="tags" multiple>${recordOptions(db.tag_records)}</select></label></div><p class="hint">Use Ctrl / Command to select multiple genres or tags. No audio file is required.</p>`,async f=>{const body={title:f.get('title').trim(),bpm:Number(f.get('bpm')),key:f.get('key')||null,duration:Number(f.get('duration')),downbeat:f.get('downbeat')===''?null:Number(f.get('downbeat')),album:f.get('album')===''?null:Number(f.get('album')),instrumental:f.get('instrumental')===''?null:f.get('instrumental')==='yes',language:f.get('language')||null,artists:f.getAll('artist').map(id=>({id:Number(id),role:f.get('role-'+id).trim()})),genre_ids:f.getAll('genres').map(Number),tag_ids:f.getAll('tags').map(Number)};if(!body.artists.length)throw validation('Select at least one artist.');if(body.downbeat!==null&&body.downbeat>=body.duration)throw validation('First downbeat must be less than the track duration.');const result=isNew?await api.create('tracks',body):await api.update('tracks',t.id,body,etag);upsert('tracks',result.data);try{db.cues=await api.all('cues')}catch{toast('Track saved; refresh data to reload derived cue bars');return}toast('Track saved')});for(const name of ['genres','tags'])Array.from($(`[name="${name}"]`).options).forEach(o=>o.selected=(t[name==='genres'?'genre_ids':'tag_ids']||[]).includes(Number(o.value)))}

function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(!leaveDraft())return;page=b.dataset.nav;activeSet=null;render()});document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>detail(+b.dataset.track));document.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{b.checked?selected.add(+b.dataset.select):selected.delete(+b.dataset.select);render()});document.querySelectorAll('[data-set]').forEach(b=>b.onclick=()=>run(()=>openSet(+b.dataset.set)));const update=()=>{if($('#results'))$('#results').innerHTML=table();if($('#builderresults'))$('#builderresults').innerHTML=builderTracks();bindResults();gate()};if($('#search'))$('#search').oninput=e=>{filters.q=e.target.value;update()};document.querySelectorAll('[data-filter]').forEach(b=>b.onchange=()=>{filters[b.dataset.filter]=b.value;update()});for(const id of ['min','max'])if($('#'+id))$('#'+id).oninput=e=>{filters[id]=e.target.value;update()};document.querySelectorAll('[data-note]').forEach(b=>b.oninput=()=>{draft.items.find(i=>i.track_id===+b.dataset.note).notes=b.value;dirty=true});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const[n,d]=b.dataset.move.split(',').map(Number);move(n,n+d)});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{draft.items=draft.items.filter(i=>i.track_id!==+b.dataset.remove);dirty=true;renumber();render()});let dragging;document.querySelectorAll('[data-drag]').forEach(b=>{b.ondragstart=e=>{if(e.target.matches('textarea,button,input')){e.preventDefault();return}dragging=+b.dataset.drag};b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();if(dragging!==undefined)move(dragging,+b.dataset.drag)}});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>run(async()=>{switch(b.dataset.action){case'newset':newSet();break;case'addtrack':await trackForm();break;case'back':if(!leaveDraft())return;activeSet=null;render();break;case'clear':Object.keys(filters).forEach(k=>filters[k]='');render();break;case'saveset':requireWrite();b.disabled=true;try{const result=await api.replaceSetItems(activeSet,draft.items.map(({track_id,notes})=>({track_id,notes})),setEtag);upsert('sets',result.data);draft=structuredClone(result.data);setEtag=result.etag;dirty=false;toast('Set arrangement saved');render()}catch(error){if(error.status===412)showSetConflict(error);else throw error}finally{b.disabled=false}break;case'rename':await renameSet();break;case'deleteset':await deleteSet();break;case'token':tokenDialog();break;case'refresh':if(!leaveDraft())return;await boot();break;}}));bindResults();gate()}

function bindResults(){document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>detail(+b.dataset.track));document.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{b.checked?selected.add(+b.dataset.select):selected.delete(+b.dataset.select);render()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>run(()=>{requireWrite();if(draft.items.length>=100)throw validation('A set supports up to 100 tracks.');dirty=true;draft.items.push({track_id:+b.dataset.add,position:draft.items.length+1,notes:'',date_added:new Date().toISOString()});render()}))}
function renumber(){draft.items.forEach((i,n)=>i.position=n+1)}function move(from,to){requireWrite();if(to<0||to>=draft.items.length)return;dirty=true;draft.items.splice(to,0,draft.items.splice(from,1)[0]);renumber();render()}
boot();
function safeColor(value){return /^#[0-9a-f]{6}$/i.test(value||'')?value:'#94a09f'}
function recordOptions(records){return records.map(r=>`<option value="${r.id}">${esc(r.name)} (#${r.id})</option>`).join('')}
function upsert(resource,record){if(!record||!Number.isSafeInteger(record.id))throw Error('Invalid API record response');db[resource]=db[resource].filter(r=>r.id!==record.id);db[resource].push(record);db[resource].sort((a,b)=>a.id-b.id)}
function requireWrite(){if(!unlocked)throw Error('Enable editing and enter the shared write token first.')}
function gate(){const selector='[data-action="newset"],[data-action="addtrack"],[data-action="rename"],[data-action="saveset"],[data-action="deleteset"],#deletetrack,[data-add],[data-remove],[data-move],[data-note],[data-select],#edittrack,#addcue,[data-editcue],[data-deletecue]';document.querySelectorAll(selector).forEach(el=>{if(!unlocked){el.disabled=true;el.title='Enable editing to modify the database'}});document.querySelectorAll('[data-drag]').forEach(el=>el.draggable=unlocked)}
function showError(error,target){target.replaceChildren();if(!error.status){const warning=document.createElement('p');warning.textContent='Network failure or timeout: the save result may be unknown. Refresh and verify before submitting again.';target.append(warning)}const text=document.createElement('p');text.textContent=error.message||'Request failed';target.append(text);for(const [field,message] of Object.entries(error.fields||{})){const line=document.createElement('p');line.textContent=`${field}: ${message}`;target.append(line)}if(error.status===412){const hint=document.createElement('p');hint.textContent='This record changed. Your input is preserved below. Copy your changes, close this form, and reopen to compare with the latest record. Saving this stale form is disabled.';target.append(hint)}}
async function run(action){try{await action()}catch(error){modal('Operation failed',`<div class="error" id="operationerror" role="alert"></div><p class="hint">A failed or interrupted write may need a fresh read to confirm its result. Do not repeat a creation request without checking.</p>`);showError(error,$('#operationerror'))}}
function leaveDraft(){if(dirty&&!confirm('Discard unsaved set arrangement changes?'))return false;dirty=false;return true}
async function openSet(id){if(!leaveDraft())return;const result=await api.get('sets',id);upsert('sets',result.data);activeSet=id;draft=structuredClone(result.data);setEtag=result.etag;dirty=false;render()}
async function renameSet(){requireWrite();if(dirty){toast('Save the arrangement before renaming this set.');return}const result=await api.get('sets',activeSet);simpleForm('Rename set',`<label>Set name<input name="name" maxlength="2000" value="${esc(result.data.name)}" required></label><p class="hint">Rename saves separately from the arrangement.</p>`,async f=>{const saved=await api.update('sets',activeSet,{name:f.get('name').trim()},result.etag);upsert('sets',saved.data);draft=structuredClone(saved.data);setEtag=saved.etag;toast('Set renamed')})}
async function deleteCue(id,trackId){requireWrite();const result=await api.get('cues',id);simpleForm('Delete cue',`<p>Delete ${esc(result.data.name)}? This removes the cue annotation permanently.</p>`,async()=>{await api.remove('cues',id,result.etag);db.cues=db.cues.filter(c=>c.id!==id);toast('Cue deleted')},'Delete cue')}
function showSetConflict(error){modal('Set changed on the server',`<div id="conflicterror" class="error"></div><h3>Your unsaved arrangement</h3><pre id="localdraft"></pre><h3>Latest server arrangement</h3><pre id="serverdraft">Use Compare to load the latest version.</pre><div class="actions"><button id="compare">Compare</button><button id="discard">Discard draft and reload</button></div><p class="hint">Your draft remains open until you explicitly discard it. No automatic overwrite is performed.</p>`);showError(error,$('#conflicterror'));$('#localdraft').textContent=JSON.stringify(draft,null,2);$('#compare').onclick=()=>run(async()=>{$('#serverdraft').textContent=JSON.stringify((await api.get('sets',activeSet)).data,null,2)});$('#discard').onclick=()=>run(async()=>{if(!confirm('Discard your draft and load the latest set?'))return;dirty=false;await openSet(activeSet);$('#modal').close()})}
function tokenDialog(){if(unlocked){api.clearWriteToken();unlocked=false;render();return}simpleForm('Enable database editing',`<label>Shared write token<input name="token" type="password" autocomplete="off" required></label><p class="hint">Stored only in memory until you lock editing or reload. The server validates the token on each write.</p>`,async f=>{api.setWriteToken(f.get('token'));unlocked=true;toast('Editing enabled; token checked when saving')},'Enable editing')}
async function boot(){const root=$('#app');root.innerHTML='<div class="empty" role="status">Loading EC2 catalogue…</div>';try{const next=await api.load();db=next;activeSet=null;draft=null;dirty=false;selected.clear();render()}catch(error){root.innerHTML='<div class="empty"><h1>Could not load the catalogue</h1><p id="loaderror" role="alert"></p><button id="retry">Retry</button></div>';$('#loaderror').textContent=error.message;$('#retry').onclick=boot}}
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue=''}});

function validation(message){return Object.assign(new Error(message),{status:422})}

async function deleteSet(){
  requireWrite();
  if(dirty){toast('Save or discard your arrangement before deleting this set.');return}
  const current=await api.get('sets',activeSet);
  simpleForm('Delete set',`<p>Permanently delete <strong>${esc(current.data.name)}</strong> and its ${current.data.items.length} set entries, including performance notes? The tracks and their cues will remain in the library.</p>`,async()=>{
    await api.remove('sets',current.data.id,current.etag);
    db.sets=db.sets.filter(s=>s.id!==current.data.id);
    activeSet=null;draft=null;setEtag=null;dirty=false;
    toast('Set deleted; library tracks retained');
  },'Delete set');
}
async function deleteTrack(id){
  requireWrite();
  if(dirty){toast('Save or discard your arrangement before deleting a track.');return}
  const current=await api.get('tracks',id);
  const memberships=db.sets.filter(s=>s.items.some(item=>item.track_id===id));
  simpleForm('Delete track',`<p>Permanently delete <strong>${esc(current.data.title)}</strong>? Its cues and artist, genre and tag associations will also be removed. Artist and catalogue records remain.</p><p class="hint">${memberships.length?'Currently listed in: '+memberships.map(s=>esc(s.name)).join(', ')+'. Remove it from every set and save those arrangements before deletion.':'The server will reject deletion if this track is still referenced by a set.'}</p>`,async()=>{
    await api.remove('tracks',id,current.etag);
    db.tracks=db.tracks.filter(t=>t.id!==id);
    db.cues=db.cues.filter(c=>c.track_id!==id);
    selected.delete(id);
    toast('Track and its dependent metadata deleted');
  },'Delete track');
}
